function updateRaffleClocks() {
 document.querySelectorAll('[data-expires]').forEach(clock=>{
  const seconds=Math.max(0,Math.floor((new Date(clock.dataset.expires).getTime()-Date.now())/1000));
  if(!Number.isFinite(seconds)){clock.textContent='Дата уточняется';return;}
  if(!seconds){clock.textContent='Завершён';return;}
  const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60),rest=seconds%60;
  clock.textContent=`${days ? days+' д ' : ''}${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(rest).padStart(2,'0')}`;
 });
}
