   more.addEventListener('click',loadParticipants);refresh.addEventListener('click',()=>{if(loading)return;cursor='';loaded=false;stale=false;list.replaceChildren();more.hidden=refresh.hidden=true;loadParticipants();});details.addEventListener('toggle',()=>{if(details.open&&!loaded)loadParticipants();});
