function pendingSpinKey(){return `skinsflip-preview:wheel-pending:${user.steamId}`;}
function readPendingSpin(){
 if(pendingSpinMemory)return pendingSpinMemory;
 try{const value=sessionStorage.getItem(pendingSpinKey());if(/^[a-f0-9]{32}$/.test(value||''))pendingSpinMemory=value;}catch{}
 return pendingSpinMemory;
}
function writePendingSpin(value){pendingSpinMemory=value;try{if(value)sessionStorage.setItem(pendingSpinKey(),value);else sessionStorage.removeItem(pendingSpinKey());}catch{}}
