  let requestId=readPendingSpin();if(!requestId){requestId=newSpinRequest();writePendingSpin(requestId);}
  const data=await api('/api/wheel/spin',{method:'POST',signal:AbortSignal.timeout(15000),body:JSON.stringify({requestId})});
  if(epoch!==pageEpoch)return;
  user.spinsAvailable=data.remainingSpins;
  const target=(270-(data.index*60+30)+360)%360;rotation+=1800+((target-rotation%360+360)%360);$('wheelCanvas').style.transform=`rotate(${rotation}deg)`;
  setTimeout(()=>{if(epoch!==pageEpoch)return;showWheelLast(data.prize);notice(`Ваш выигрыш: ${money(data.prize)}`);$('spinsCount').textContent=`Доступно вращений: ${user.spinsAvailable}`;writePendingSpin(null);updateSpinRecovery();btn.disabled=false;},typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches?20:4100);
