  if(id==='adminIntegrations'){const rows=[],steam=data.steam,when=value=>value?new Date(value).toLocaleString('ru-RU'):'нет данных';const steamText=steam.retryAfterSeconds?`Steam ограничил запросы · ${when(steam.lastLimitedAt)} · пауза сайта: ${steam.retryAfterSeconds} с`:steam.lastOutcome==='limited'?`Последний ответ: ограничение Steam · ${when(steam.lastAttemptAt)} · пауза сайта закончилась; статус Steam неизвестен`:steam.lastOutcome==='available'?`Последний запрос обработан · ${when(steam.lastAttemptAt)}`:steam.lastOutcome==='partial'?`Инвентарь получен частично · ${when(steam.lastAttemptAt)}`:steam.lastOutcome==='failed'?`Последний запрос завершился ошибкой · ${when(steam.lastAttemptAt)}`:'Запросов с момента запуска не было';rows.push(adminRow('Инвентарь Steam',steamText));const names={'730':'CS2','570':'Dota 2','252490':'Rust'};for(const p of data.prices){const text=p.outcome==='available'?`Последняя загрузка данных: ${when(p.lastSuccessAt)} · время источника: ${when(p.sourceAt)}`:p.outcome==='failed'?`Последняя попытка не удалась: ${when(p.lastAttemptAt)} · предыдущая загрузка: ${when(p.lastSuccessAt)}`:'Загрузок с момента запуска не было';rows.push(adminRow('Цены '+names[p.game],text));}rows.push(adminRow('Выкуп предметов','Интеграция не подключена'));rows.push(adminRow('Выплаты','Интеграция не подключена'));$(id).replaceChildren(...rows);}
